import { CHAIN } from './chain-config.js';
import { get, subscribe } from './store.js';
import { formatJackpotCountdown } from './jackpot-countdown.js';

export function sessionStatusText(state, nowSeconds = Date.now() / 1000, chain = CHAIN) {
  if (chain.deploymentReady === false) return 'The next Base Sepolia testnet is being prepared. Gameplay opens after deployment.';
  if (state?.gameOver || !(Number(state?.lastDailyCompletedAt) > 0) || !(Number(state?.hardStallAt) > 0)) return '';
  const left = Math.max(0, Number(state.hardStallAt) - nowSeconds);
  return left > 0 ? `Hard stall in ${formatJackpotCountdown(left)} if no daily round completes.`
    : 'Daily progress has stalled. Mine to process the game ending.';
}
export function mountSessionStatus(root = globalThis.document) {
  const node = root?.querySelector('[data-bind="session-status"]');
  if (!node) return () => {};
  const paint = () => { node.textContent = sessionStatusText(get('app.gameState')); node.hidden = !node.textContent; };
  const unsubscribe = subscribe('app.gameState', paint);
  const timer = setInterval(paint, 1000); timer?.unref?.();
  paint();
  return () => { unsubscribe(); clearInterval(timer); };
}
